@slots literal
{
  "cases": [
    {
      "label": "A",
      "properties": {
        "has water": true,
        "has air": true,
        "the temperature is suitable": true,
        "the shoot receives light": false
      }
    },
    {
      "label": "B",
      "properties": {
        "has water": true,
        "has air": false,
        "the temperature is suitable": true,
        "the shoot receives light": true
      }
    },
    {
      "label": "C",
      "properties": {
        "has water": false,
        "has air": true,
        "the temperature is suitable": true,
        "the shoot receives light": true
      }
    },
    {
      "label": "D",
      "properties": {
        "has water": true,
        "has air": true,
        "the temperature is suitable": true,
        "the shoot receives light": true
      }
    }
  ],
  "required": [
    "has air",
    "has water",
    "the shoot receives light",
    "the temperature is suitable"
  ],
  "forbidden": []
}

@answer jsEval
const slots = $slots;
for (const entry of slots.cases) {
}
const matching = slots.cases.filter((entry) => slots.required.every((property) => entry.properties[property] === true) && slots.forbidden.every((property) => entry.properties[property] === false));
probe(matching.length > 0, "at least one case must satisfy the competition rule");
probe(matching.length === 1, "the competition rule must leave exactly one case, not " + matching.length);
return "Case " + matching[0].label + ".";

